-- ============================================================================
-- TICKET-ADV017 — Seed data: 500 trades (+ recon_breaks + settlements)
--
-- Deterministic, portable SQL (runs on H2 dev + PostgreSQL uat/prod).
-- Trades are spread evenly across the four monthly partitions Apr–Jul 2026
-- (trade_date = 2026-04-01 + ((n-1) mod 120) days).
-- id is auto-generated; on a fresh DB the 500 rows take ids 1..500.
-- Idempotency + prod-gating is handled by the changeSet in 008-seed.xml
-- (context="dev,test" + a COUNT(*)=0 precondition).
-- ============================================================================


-- A recon break for every UNMATCHED / DISPUTED trade (~100 rows).
SELECT id,
       CASE MOD(id, 3)
           WHEN 0 THEN 'PRICE_MISMATCH'
           WHEN 1 THEN 'QUANTITY_MISMATCH'
           ELSE 'DATE_MISMATCH'
       END,
       'OPEN'
FROM trades
WHERE status IN ('UNMATCHED', 'DISPUTED');

-- One settlement per MATCHED trade so the ADV011 lifecycle CTE has data.
SELECT id, trade_date, quantity * price, 'SETTLED'
FROM trades
WHERE status = 'MATCHED';
